#nullable enable // autogenerated

using System;
using PVZEngine;
using PVZEngine.Base;
using UnityEngine;

namespace MVZ2.Managers
{
    [CreateAssetMenu(fileName = "NewGameSettings", menuName = "MVZ2/Game Settings")]
    public class GameSettings : ScriptableObject
    {
        public int GetHPBarLayerOrder(NamespaceID id)
        {
            return Array.FindIndex(hpBarLayerOrders, r => r.Compare(id));
        }
        public NamespaceID GetDebugStageArea(int index)
        {
            return debugLevelAreas[index].Get();
        }
        public NamespaceID DefaultDifficultyID => defaultDifficultyID.Get();
        public Sprite DefaultStarshardSprite => defaultStarshardSprite;
        public NamespaceID HelpNoteID => helpNoteID.Get();
        public NamespaceID FirstLevelAreaID => firstLevelAreaID.Get();
        public NamespaceID FirstLevelStageID => firstLevelStageID.Get();
        public NamespaceID DefaultMapID => defaultMapID.Get();
        public NamespaceID MainMapID => mainMapID.Get();
        public NamespaceID GridPlaceHolderModelID => gridPlaceHolderModelID.Get();
        public NamespaceID DebugLevelStageID => debugLevelStageID.Get();
        public int DebugStageAreaCount => debugLevelAreas.Length;
        [SerializeField]
        private NamespaceIDReference defaultDifficultyID = null!;
        [SerializeField]
        private Sprite defaultStarshardSprite = null!;
        [SerializeField]
        private NamespaceIDReference helpNoteID = null!;
        [SerializeField]
        private NamespaceIDReference firstLevelAreaID = null!;
        [SerializeField]
        private NamespaceIDReference firstLevelStageID = null!;
        [SerializeField]
        private NamespaceIDReference defaultMapID = null!;
        [SerializeField]
        private NamespaceIDReference mainMapID = null!;
        [SerializeField]
        private NamespaceIDReference gridPlaceHolderModelID = null!;
        [SerializeField]
        private NamespaceIDReference[] hpBarLayerOrders = null!;
        [SerializeField]
        private NamespaceIDReference debugLevelStageID = null!;
        [SerializeField]
        private NamespaceIDReference[] debugLevelAreas = null!;
    }
}
